"<b style=\"color:var(--err)\">fehlen</b> – Enden auf Wand, Stütze oder Außenwand legen": "<b style=\"color:var(--err)\">missing</b> – place ends on a wall, column or external wall",
"<b>ABC:</b> Außenluft nur über Gasfilter, Raum unter leichtem Überdruck, gasdichte Türen, Schleuse zum Ein- und Ausgehen.": "<b>CBRN:</b> outdoor air only via gas filter, room under slight overpressure, gastight doors, airlock for entry and exit.",
"<b>Brand:</b> Außenluft, Rauch und Betrieb bei geschlossener Ansaugung benötigen ein abgestimmtes Lüftungs- und Brandschutzkonzept. Umluft ersetzt keine Frischluft; CO, CO₂ und Sauerstoffversorgung berücksichtigen.": "<b>Fire:</b> outdoor air, smoke and operation with the intake closed require a coordinated ventilation and fire safety strategy. Recirculated air does not replace fresh air; consider CO, CO₂ and oxygen supply.",
"<b>EMP:</b> Geschlossener Metallschirm um den Innenraum, Lüftung über Wabenkamine, jede Stromleitung über Filter, Daten nur per Glasfaser, Türen HF-dicht. Schirmdämpfung nach dem Einbau messen lassen.": "<b>EMP:</b> closed metal shield around the interior, ventilation via honeycomb vents, every power line via a filter, data via optical fibre only, doors RF-tight. Have the shielding effectiveness measured after installation.",
"<b>Erschütterung:</b> Lüftungsgerät, Batterien, Tanks und Regale schocksicher befestigen (±2 g horizontal, ±4 g vertikal). Nichts an die Decke hängen, was herunterfallen kann.": "<b>Shock:</b> fix the ventilation unit, batteries, tanks and shelving shock-resistantly (±2 g horizontal, ±4 g vertical). Do not hang anything from the ceiling that could fall down.",
"<b>Gespeichertes Projekt nicht geladen</b> ({msg}). Es wurde nicht überschrieben, sondern im Browser aufgehoben.": "<b>Saved project not loaded</b> ({msg}). It has not been overwritten but kept in the browser.",
"<b>Luftstoß:</b> Decke, Außenwände und Bodenplatte bekommen den außergewöhnlichen Lastfall, Ergebnis unter Tragwerk. Schutztüren, Luken und Explosionsschutzventile müssen für {p} bar geprüft sein.": "<b>Air blast:</b> the roof slab, external walls and base slab receive the accidental load case; results under Structure. Protective doors, hatches and blast valves must be tested for {p} bar.",
"<b>Mindestwerte TWK:</b> Decke und Außenwände ab 30 cm, Bodenplatte ab {t} cm, tragende Innenwände ab 20 cm, Bewehrung mindestens 0,18 % je Zugseite, nur B500B.": "<b>TWK minimum values:</b> roof slab and external walls from 30 cm, base slab from {t} cm, load-bearing internal walls from 20 cm, reinforcement at least 0.18% per tension face, B500B only.",
"<b>Strahlung:</b> Über dem Raum mindestens 65 cm Betonäquivalent, Erde zählt mit 1.600 kg/m³. Zugang mit Richtungswechsel, damit keine Direktstrahlung in den Raum fällt.": "<b>Radiation:</b> at least 65 cm concrete equivalent above the room; soil counts at 1,600 kg/m³. Access with a change of direction so that no direct radiation enters the room.",
"<b>η (Ausnutzung)</b> = Last geteilt durch Tragfähigkeit. Unter 1,0 hält das Bauteil, 0,9–1,0 ist knapp, über 1,0 ist es überlastet.": "<b>η (utilisation)</b> = load divided by resistance. Below 1.0 the member holds, 0.9–1.0 is marginal, above 1.0 it is overloaded.",
