"Abschätzung: Diffusion nach dem Ansatz der spanischen DB HS 6 mit D = 1·10⁻⁸ m²/s für dichten, rissbeschränkten Beton; Raumluftbilanz mit Zerfall. Der Haupteintrag läuft über Fugen, Risse und Durchführungen und lässt sich nicht vorausberechnen – deshalb zählt die Ausführung, und nur eine Messung zeigt den tatsächlichen Wert.": "Estimate: diffusion following the Spanish DB HS 6 approach with D = 1·10⁻⁸ m²/s for dense, crack-limited concrete; indoor air balance including decay. Most radon enters through joints, cracks and penetrations and cannot be predicted – workmanship is what counts, and only a measurement shows the actual value.",
