"Anforderung {cls} für tragende Bauteile. Nachweis mit dem Tabellenverfahren nach DIN EN 1992-1-2 (Abschnitt 5): Mindestabmessungen und Achsabstand a der Längsbewehrung (a = c + Ø/2, bei Stützen und Balken zuzüglich Bügel). Brandbeanspruchung von innen.": "Requirement {cls} for load-bearing members. Verification using tabulated data to DIN EN 1992-1-2 (Section 5): minimum dimensions and axis distance a of the longitudinal reinforcement (a = c + Ø/2, plus links for columns and beams). Fire exposure from inside.",
"Anforderung {cls} für tragende Bauteile. Nachweis mit dem Tabellenverfahren nach EN 1992-1-2 (Abschnitt 5): Mindestabmessungen und Achsabstand a der Längsbewehrung (a = c + Ø/2, bei Stützen und Balken zuzüglich Bügel). Brandbeanspruchung von innen.": "Requirement {cls} for load-bearing members. Verification using tabulated data to EN 1992-1-2 (Section 5): minimum dimensions and axis distance a of the longitudinal reinforcement (a = c + Ø/2, plus links for columns and beams). Fire exposure from inside.",
"Anforderung {cls} für tragende Bauteile. Nachweis sinngemäß mit dem Tabellenverfahren nach EN 1992-1-2 (Abschnitt 5): Mindestabmessungen und Achsabstand a der Längsbewehrung (a = c + Ø/2, bei Stützen und Balken zuzüglich Bügel); Brandschutz in der Schweiz nach VKF-Brandschutzvorschriften. Brandbeanspruchung von innen.": "Requirement {cls} for load-bearing members. Verification by analogy using tabulated data to EN 1992-1-2 (Section 5): minimum dimensions and axis distance a of the longitudinal reinforcement (a = c + Ø/2, plus links for columns and beams); fire protection in Switzerland to the VKF fire protection regulations. Fire exposure from inside.",
"Anforderung {cls}, angesetzt als Feuerwiderstandsdauer {h} h. Nachweis mit den Tabellen nach ACI/TMS 216.1-14: äquivalente Mindestdicke der Platten und Wände (Tab. 4.2, kieseliger Zuschlag), Betondeckung der Platten (Tab. 4.3.1.1) und Balken (Tab. 4.3.1.2) ohne Ansatz behinderter Verformung, Stützen Mindestmaß (4.5.1) und Deckung 25 mm je Stunde, höchstens 50 mm (4.5.3). Verglichen wird die Betondeckung c. Brandbeanspruchung von innen.": "Requirement {cls}, taken as a fire resistance rating of {h} h. Verification with the tables of ACI/TMS 216.1-14: minimum equivalent thickness of slabs and walls (Table 4.2, siliceous aggregate), cover of slabs (Table 4.3.1.1) and beams (Table 4.3.1.2) without taking restraint into account, minimum column dimension (4.5.1) and cover 25 mm per hour, at most 50 mm (4.5.3). The concrete cover c is compared. Fire exposure from inside.",
