"Automatik nur für ideale sphärische Luftdetonation mit 0,05 ≤ Z ≤ 40. Erdüberdeckung, Abschirmung, Bodenreflexion, Kontakt, Penetration, Splitter und thermobarische Nachwirkung sind darin nicht enthalten. Der Druck wird nicht mit der Trefferzahl multipliziert und nicht automatisch als TWK-Flächenlast angesetzt.": "Automatic calculation only for an ideal spherical air burst with 0.05 ≤ Z ≤ 40. Earth cover, shielding, ground reflection, contact, penetration, fragments and thermobaric after-effects are not included. The pressure is not multiplied by the number of hits and is not automatically applied as a TWK area load.",
