"Außenwände als FE-Platten je Wandseite (Achsmaße): an Decke und Bodenplatte gelenkig mit Drehfeder aus der Plattensteifigkeit (3,5 EI/l), an Zwischendecken und tragenden Innenwänden linienförmig gestützt, Öffnungen ausgespart; Wandecken als Grenzfälle eingespannt und gelenkig (Hülle). Rahmenecke außen mindestens mit dem Eckmoment der Plattenrechnung.": "External walls as FE plates per wall side (centreline dimensions): pinned at roof slab and base slab with rotational spring from the slab stiffness (3.5 EI/l), line-supported at intermediate slabs and load-bearing internal walls, openings omitted; wall corners as limiting cases fixed and pinned (envelope). Outer frame corner designed for at least the corner moment from the slab analysis.",
"Außenwände als FE-Platten je Wandseite (Drehfedern an Decke und Bodenplatte, Linienlager an Zwischendecken und tragenden Innenwänden, Öffnungen ausgespart), Ecken eingespannt und gelenkig als Grenzfälle; Erdruhedruck plus Wasserdruck": "External walls as FE plates per wall side (rotational springs at roof slab and base slab, line supports at intermediate slabs and load-bearing internal walls, openings cut out), corners fixed and pinned as limiting cases; earth pressure at rest plus water pressure",
