"Bemessung der Platten je Knoten für Biegung (EC2 6.1), Querkraft (6.2), Rissbreite unter quasi-ständiger Last (7.3.4) und Zwang (7.3.2); Grundbewehrung je Lage, Zulagen in Bereichen höherer Beanspruchung.": "Slab design at each node for bending (EC2 6.1), shear (6.2), crack width under quasi-permanent load (7.3.4) and restraint (7.3.2); basic reinforcement per layer, additional bars in areas of higher stress.",
"Bemessung der Platten je Knoten für Biegung ({b}), Querkraft ({s}) und Rissbeschränkung ({c}); Grundbewehrung je Lage, Zulagen in Bereichen höherer Beanspruchung.": "Slab design at each node for bending ({b}), shear ({s}) and crack control ({c}); basic reinforcement per layer, additional bars in areas of higher stress.",
