"Bemessungsbeschleunigung ag = γf · agd": "Design ground acceleration ag = γf · agd",
"Bemessungsdicken übernehmen": "Apply design thicknesses",
"Bemessungsdruck {q} kN/m². Jede Luftöffnung der Hülle braucht ein Explosionsschutzventil; Abgasventile hitzebeständig.": "Design pressure {q} kN/m². Every air opening in the envelope requires a blast valve; exhaust valves heat-resistant.",
"Bemessungsgrundlage": "Design basis",
"Bemessungslast": "Design load",
"Bemessungslast Fläche": "Design load, area",
"Bemessungsmomente an Auflagern über 2·d gemittelt, im Feld ungemittelt (Abschnitt 2.3). Stützmomente an Singularitäten konvergieren langsamer; Abweichungen bis rund 10 % sind bei halbierter Netzweite üblich.": "Design moments at supports averaged over 2·d, not averaged in the span (section 2.3). Support moments at singularities converge more slowly; deviations of up to approx. 10 % are usual when the mesh size is halved.",
"Bemessungsmomente der Platten bis 1,5·d vor Auflagern, Stützen, Aussparungsrändern und unter Einzellasten über eine Breite von 2·d gemittelt (Quadrat ±d um jeden Knoten): Spitzen dort sind Singularitäten der Plattentheorie und hängen sonst von der Netzweite ab. Die Mittelungsbreite entspricht etwa c + d (Rombach, Anwendung der FEM im Betonbau). Im Feld werden die Knotenwerte ungemittelt bemessen. Unterzüge erhalten den Lastverlauf aus den FE-Auflagerkräften (über 0,5 m geglättet).": "Design moments of the slabs within 1.5·d of supports, columns, opening edges and under point loads are averaged over a width of 2·d (square ±d around each node): peaks there are singularities of plate theory and would otherwise depend on the mesh size. The averaging width corresponds approximately to c + d (Rombach, Anwendung der FEM im Betonbau). In the spans, node values are designed without averaging. Downstand beams receive the load distribution from the FE support reactions (smoothed over 0.5 m).",
"Bemessungswasserstand": "Design groundwater level",
