"Das Formular hat sich seit der letzten Prüfung geändert – neue Fassung verwenden.": "The form has changed since the last check – use the new version.",
"Das Tafelverfahren rechnet jedes Feld für sich mit Hüllwerten und liegt meist deutlich auf der sicheren Seite. Bemessen wird mit der FE-Rechnung.": "The tabulated coefficient method calculates each span separately with envelope values and is usually well on the safe side. Design is based on the FE analysis.",
"Das Tool ersetzt keine unterschriebene Statik mit Bewehrungsplänen. Leere Beträge = Richtwert nach Bauwerksgröße.": "The tool does not replace signed structural calculations with reinforcement drawings. Empty amounts = guide value based on structure size.",
"Das Vergleichspaket enthält Eingaben, Systeme, Lastfälle, Kombinationen und Ergebnisse je Position – zum Nachrechnen mit einem eigenen Statikprogramm. Die DXF-Datei liefert die Systemlinien dazu.": "The cross-check package contains inputs, structural systems, load cases, combinations and results per item – for recalculation with your own structural analysis software. The DXF file provides the corresponding system lines.",
