"Dekontamination": "Decontamination",
"Den Schutzgrad hast du schon gewählt (Schritt <a data-goto=\"schutzgrad\">Schutzgrad</a>). Hier kommen die Nachweise dazu: geforderte Treffer, Schichten je Bauteil und die Prüfunterlagen. Das macht erst Sinn, wenn Grundriss und Dicken stehen.": "You have already chosen the protection level (step <a data-goto=\"schutzgrad\">Protection level</a>). This is where the verifications are added: required hits, layers per member and the test documents. This only makes sense once the floor plan and thicknesses are fixed.",
"Denkmalschutz": "Heritage protection",
"Der Baugrund drückt mit {p} kN/m² von unten gegen die Platte.": "The ground pushes up against the slab with {p} kN/m².",
"Der Boden unter der Platte bekommt {e} kN/m² und darf {r} kN/m² aufnehmen.": "The ground beneath the slab receives {e} kN/m² and may take up to {r} kN/m².",
"Der Bunker belastet den Boden um {p} kN/m² mehr, als der Aushub entlastet.": "The bunker loads the ground by {p} kN/m² more than the excavation unloads it.",
"Der Bunker ist leichter als der ausgehobene Boden – der Boden wird nur wiederbelastet (Steifemodul ×3).": "The bunker is lighter than the excavated soil – the ground is only reloaded (oedometer modulus ×3).",
"Der Rohbau trägt.": "The structure holds.",
"Der USGS-Abruf braucht den lokalen Server: python server.py starten.": "The USGS lookup needs the local server: start python server.py.",
"Der Unterzug liegt unter der {slab} und trägt sie wie eine Wand. Im Plattenmodell ist er ein starres Auflager; seine Auflagerkräfte gehen an Wände und Stützen. Bemessen als Durchlaufträger mit Rechteckquerschnitt (Plattenanteil mitgerechnet), Feldweise Verkehrslast.": "The downstand beam sits beneath the {slab} and supports it like a wall. In the slab model it is a rigid support; its support reactions are transferred to walls and columns. Designed as a continuous beam with rectangular cross-section (slab portion included), imposed load as pattern loading.",
"Der Unterzug trägt die Platte über dieser Ebene und leitet die Last an Wände oder Stützen an seinen Enden.": "The downstand beam supports the slab above this level and transfers the load to walls or columns at its ends.",
"Der entfernteste Punkt im Schutzraum liegt {d} m Luftlinie vom nächsten Zugang. Für Räumung und Rettung einen weiteren Zugang oder Notausstieg vorsehen (Orientierung: Rettungswege in Arbeitsstätten höchstens 35 m).": "The furthest point in the shelter is {d} m in a straight line from the nearest access. For evacuation and rescue, provide a further access or emergency exit (guide: escape routes in workplaces max. 35 m).",
