"Ein Schutzraum nach TWK geht davon aus, dass er kein direktes Ziel ist. Treffer, Nahtreffer und Raketen rechnet das Tool bewusst nicht: Dafür braucht es Waffenwirkungsdaten und eine Fachbemessung für militärische Schutzbauten. Forderst du so ein Szenario, steht es als offene Anforderung in Freigaben und Bericht.": "A shelter to TWK assumes that it is not a direct target. The tool deliberately does not calculate direct hits, near misses or missiles: that requires weapon effects data and specialist design for military protective structures. If you require such a scenario, it is listed as an open requirement in Approvals and the report.",
"Einbau": "Equipment",
