"Erddruck auf die Außenwände wird auf der sicheren Seite mit voller Hügelhöhe angesetzt. Zugänge werden als Einschnitt mit Stützwänden bis zum Hügelfuß geführt, der Notausstieg bis über die Hügeloberfläche.": "Earth pressure on the external walls is conservatively based on the full mound height. Accesses are formed as cuttings with retaining walls up to the mound toe, the emergency exit up to above the mound surface.",
"Erddruck charakteristisch oben / unten": "Characteristic earth pressure top / bottom",
"Erddruckzuwachs auf die nicht nachgebenden Außenwände für das Bemessungsbeben (IBC 1803.5.12) mit kh = 0,4 · SDS = {kh} (Wood, wie EN 1998-5 Anhang E.9): Δp = kh · γ · H = {dp} kN/m² über H = {H} m. Erdbebenkombination 1,2 D + E + 0,5 L mit Erddruck H × 1,6 (ASCE 7-22 2.3.6); Verhältnis zur Grundkombination höchstens {r}.": "Earth pressure increment on the non-yielding external walls for the design earthquake (IBC 1803.5.12) with kh = 0.4 · SDS = {kh} (Wood, as EN 1998-5 Annex E.9): Δp = kh · γ · H = {dp} kN/m² over H = {H} m. Seismic combination 1.2 D + E + 0.5 L with earth pressure H × 1.6 (ASCE 7-22 2.3.6); ratio to the fundamental combination at most {r}.",
"Erddruckzuwachs auf die starren Außenwände nach DIN EN 1998-5 Anhang E.9: ΔPd = α · S · γ · H² = {dP} kN/m, als Gleichlast Δp = α · S · γ · H = {dp} kN/m² über H = {H} m. Erdbebenkombination G + ψ₂·Q + AEd (γ = 1,0, Geländelast ψ₂ = {psi}); Verhältnis zur Grundkombination höchstens {r}.": "Increase in earth pressure on the rigid external walls to DIN EN 1998-5 Annex E.9: ΔPd = α · S · γ · H² = {dP} kN/m, as uniform load Δp = α · S · γ · H = {dp} kN/m² over H = {H} m. Seismic combination G + ψ₂·Q + AEd (γ = 1.0, surface load ψ₂ = {psi}); ratio to the fundamental combination at most {r}.",
"Erddruckzuwachs auf die starren Außenwände nach {ref} Anhang E.9: ΔPd = α · S · γ · H² = {dP} kN/m, als Gleichlast Δp = α · S · γ · H = {dp} kN/m² über H = {H} m. Erdbebenkombination G + ψ₂·Q + AEd (γ = 1,0, Geländelast ψ₂ = {psi}); Verhältnis zur Grundkombination höchstens {r}.": "Earth pressure increment on the rigid external walls to {ref} Annex E.9: ΔPd = α · S · γ · H² = {dP} kN/m, as a uniform load Δp = α · S · γ · H = {dp} kN/m² over H = {H} m. Seismic combination G + ψ₂·Q + AEd (γ = 1.0, ground surcharge ψ₂ = {psi}); ratio to the fundamental combination at most {r}.",
