"Ersatzbalken in Richtung der kurzen Stützweite, beidseitig eingespannt, Widerstand aus der Bruchlinientraglast, Steifigkeit mit halb gerissenem Querschnitt. Grenzwerte μ ≤ 3 (entspricht Φ = 1,2 der TWK beim Rechteckstoß) und Auflagerdrehwinkel θ ≤ 2° (UFC 3-340-02). Abplatzen, Durchschlag und Splitter sind nicht enthalten – bei Szenarien bleibt die Fachbemessung nötig.": "Equivalent beam in the direction of the short span, fixed at both ends, resistance from the yield line ultimate load, stiffness based on a half-cracked cross-section. Limits μ ≤ 3 (corresponds to Φ = 1.2 of the TWK for a rectangular pulse) and support rotation θ ≤ 2° (UFC 3-340-02). Spalling, perforation and fragments are not included – for scenarios, specialist design is still required.",
"Ersatzbalken je Bauteil in Richtung der kurzen Stützweite, beidseitig eingespannt (Biggs: KE = 307·EIa/l⁴, bei der Decke mit dem Steifigkeitsverhältnis der eingespannten Rechteckplatte nach Timoshenko Tab. 35). Lastmassenfaktor der Wand KLM = 0,77 elastisch, 0,66 plastisch (Biggs); Decke als allseits eingespannte Rechteckplatte mit KLM aus der statischen Biegefläche (elastisch) bzw. dem Bruchlinienmechanismus (plastisch) je Seitenverhältnis. Bei Fließen gilt über den ganzen Verlauf der Mittelwert aus elastisch und plastisch (Spalte KLM). Widerstand Ru aus der Bruchlinien- bzw. Fließgelenktraglast mit dynamischen Festigkeiten, Steifigkeit mit Ia = (Ig + Icr)/2 (UFC 3-340-02). Ständige Last in Stoßrichtung zu Beginn im Gleichgewicht. Lastverlauf: TWK als Rechteckstoß langer Dauer, Szenarien als Dreieck mit td = 2·I/P. Dynamische Auflagerkraft V = 0,38·R + 0,12·P (Biggs), bei der Decke mit dem Anteil der langen Seite. Grenzwerte: μ ≤ 3 (entspricht beim Rechteckstoß Φ = 1,2 der TWK), Auflagerdrehwinkel θ ≤ 2° (UFC 3-340-02, Schutzkategorie 1).": "Equivalent beam per member in the direction of the short span, fixed at both ends (Biggs: KE = 307·EIa/l⁴; for the roof slab with the stiffness ratio of the fixed rectangular plate to Timoshenko Table 35). Load-mass factor of the wall KLM = 0.77 elastic, 0.66 plastic (Biggs); roof slab as a rectangular plate fixed on all sides with KLM from the static deflected shape (elastic) or the yield-line mechanism (plastic) for each aspect ratio. Where yielding occurs, the mean of the elastic and plastic values applies over the whole response (column KLM). Resistance Ru from the yield-line or plastic-hinge collapse load with dynamic strengths, stiffness with Ia = (Ig + Icr)/2 (UFC 3-340-02). Permanent load in the blast direction initially in equilibrium. Load history: TWK as a long-duration rectangular pulse, scenarios as a triangle with td = 2·I/P. Dynamic support reaction V = 0.38·R + 0.12·P (Biggs); for the roof slab with the share of the long side. Limits: μ ≤ 3 (for the rectangular pulse this corresponds to Φ = 1.2 of the TWK), support rotation θ ≤ 2° (UFC 3-340-02, protection category 1).",
