"Je Bauteil Pläne der unteren und oberen Lage, Abwicklung der Außenwände, Stützen und Unterzüge, dazu die Biegeliste mit Biegeformen. Die BVBS-Datei (BF2D) lesen Biegemaschinen und Biegelisten-Programme ein.": "Drawings of the bottom and top layers per member, developed elevation of the external walls, columns and downstand beams, plus the bar bending schedule with shape codes. The BVBS file (BF2D) can be imported by bending machines and bending schedule software.",
"Je Gewerk laufen höchstens so viele Vorgänge gleichzeitig, wie Kolonnen da sind. Mit einer Rohbaukolonne entstehen die Zugänge in den Wartezeiten des Rohbaus.": "Per trade, no more activities run at the same time than there are crews. With one shell crew, the accesses are built during the shell's waiting times.",
"Jede Ebene hat eigene Wände, Türen, Räume und Stützen. Wände der Ebene darüber erscheinen gestrichelt; tragende Wände möglichst übereinander stellen, sonst muss die Zwischendecke die Last abfangen.": "Each level has its own walls, doors, rooms and columns. Walls of the level above appear dashed; place load-bearing walls above one another where possible, otherwise the intermediate slab must carry the load.",
