"Normwerte siehe Abschnitt 2.4. Bemessung in SI-Einheiten (ACI 318-19, Ausgabe in SI); Betonstahl {steel}. Nicht umgesetzt bzw. sinngemäß: ACI 350 (WU-Rissbreite nach EN 1992-1-1), zweiachsige Stützeninteraktion wie EN 1992-1-1 5.8.9. Die Ergebnisse sind vom verantwortlichen Tragwerksplaner (Engineer of Record) zu prüfen.": "Code values see section 2.4. Design in SI units (ACI 318-19, SI edition); reinforcing steel {steel}. Not implemented or by analogy: ACI 350 (watertight crack width to EN 1992-1-1), biaxial column interaction as EN 1992-1-1 5.8.9. The results must be checked by the Engineer of Record.",
"Normwerte siehe Abschnitt 2.4. Teile ohne Beleg in den zugänglichen Quellen (Theorie II. Ordnung der Stützen, Biegeschlankheit, Übergreifung, Betondeckung, Brandschutz, Zuordnung der Rissbeschränkungskurven) sind sinngemäß nach EN 1992-1-1 bzw. vorsichtig angesetzt und mit SIA 262 abzugleichen.": "Code values see section 2.4. Parts without evidence in the accessible sources (second-order analysis of columns, slenderness, laps, concrete cover, fire protection, assignment of the crack control curves) are taken by analogy to EN 1992-1-1 or conservatively and must be reconciled with SIA 262.",
