"Platten zweiachsig: Feldmomente gelenkig gelagert (Timoshenko-Tafeln), Stützmomente an Innenwänden nach Pieper/Martens, an Außenwänden eingespannt bzw. Rahmenecke; Auflagerkräfte aus einer FE-Vergleichsrechnung": "Two-way slabs: span moments for pinned supports (Timoshenko tables), support moments at internal walls to Pieper/Martens, at external walls fixed or frame corner respectively; support reactions from a comparative FE analysis",
