"Platten: Bemessungsmomente (an Auflagern über 2·d gemittelt) und Auflagerkräfte vergleichen, nicht Knotenspitzen an Stützen und Wandenden": "Slabs: compare design moments (averaged over 2·d at supports) and support reactions, not nodal peaks at columns and wall ends",
"Platten: Finite Elemente (schubweiche Plattenelemente, Netz ≈ {h} m); tragende Innenwände und Unterzüge als starre Linienlager, Stützen als Flächenlager, Außenwände als Rahmenecke mit Drehfeder; Bodenplatte elastisch gebettet (Bettungsmodul aus dem Steifemodul), abhebende Bereiche iterativ ausgeschaltet. Verkehrslasten zusätzlich feldweise.": "Slabs: finite elements (shear-flexible plate elements, mesh ≈ {h} m); load-bearing internal walls and downstand beams as rigid line supports, columns as area supports, external walls as frame corners with rotational springs; base slab on elastic foundation (modulus of subgrade reaction derived from the oedometer modulus), lift-off areas eliminated iteratively. Imposed loads additionally applied span by span.",
