"Schwarz: kritischer Pfad. Dauern in Arbeitstagen, Wartezeiten (Ausschalen nach 14, Erdauflast nach 28 Kalendertagen) als Abstand. Dauer anklicken und überschreiben.": "Black: critical path. Durations in working days, waiting times (striking after 14, earth load after 28 calendar days) shown as gaps. Click a duration to overwrite it.",
"Schwere Einbauten als Flächenlasten auf ihrer Aufstellfläche: Eigengewicht als ständige Last G (D), Füllung von Tanks und Regalen als Lagerlast E, auf der sicheren Seite mit dem größeren Beiwert von Flüssigkeitslast F (wie D) und Nutzlast L; Dauerlastanteil {p2}. Für das Aggregat Schwingbeiwert 1,2. Massen sind Richtwerte der Vorplanung und durch Herstellerangaben zu ersetzen.": "Heavy installations as area loads on their footprint: self-weight as dead load G (D), contents of tanks and shelving as storage load E, on the safe side with the larger factor of fluid load F (as D) and live load L; sustained portion {p2}. Dynamic factor 1.2 for the generator. Masses are preliminary guide values and must be replaced by manufacturer data.",
"Schwere Einbauten als Flächenlasten auf ihrer Aufstellfläche: Eigengewicht als ständige Last G, Füllung von Tanks und Regalen als Lagerlast E (DIN EN 1991-1-1/NA Kat. E: ψ₀ = 1,0, ψ₂ = 0,8). Für das Aggregat Schwingbeiwert 1,2. Massen sind Richtwerte der Vorplanung und durch Herstellerangaben zu ersetzen.": "Heavy installed equipment as area loads on its footprint: self-weight as permanent load G, contents of tanks and shelving as storage load E (DIN EN 1991-1-1/NA cat. E: ψ₀ = 1.0, ψ₂ = 0.8). Dynamic factor 1.2 for the generator. Masses are preliminary guide values and must be replaced by manufacturer's data.",
"Schwere Einbauten als Flächenlasten auf ihrer Aufstellfläche: Eigengewicht als ständige Last G, Füllung von Tanks und Regalen als Lagerlast E (Kat. E: ψ₀ = {p0}, ψ₂ = {p2}). Für das Aggregat Schwingbeiwert 1,2. Massen sind Richtwerte der Vorplanung und durch Herstellerangaben zu ersetzen.": "Heavy installed equipment as area loads on its footprint: self-weight as permanent load G, contents of tanks and shelving as storage load E (cat. E: ψ₀ = {p0}, ψ₂ = {p2}). Dynamic factor 1.2 for the generator. Masses are preliminary guide values and must be replaced by manufacturer's data.",
