"Stationäre Bilanz: Wände, Decke und Sohle geben Wärme ans Erdreich ab (halber Wert, weil sich das Erdreich bei langer Belegung erwärmt); Außenluft wärmer als innen bringt zusätzliche Wärme. Rückkühler außen braucht gasdichte, druckstoßfeste Durchführungen.": "Steady-state balance: walls, roof slab and base slab release heat to the ground (half value, as the ground warms up during prolonged occupancy); outdoor air warmer than indoors adds heat. An external dry cooler requires gastight, blast-resistant penetrations.",
